def min_time_to_deliver_candies(n, m, candies):
    def bfs(start):
        queue = [(start, 0)]
        visited = set([start])
        while queue:
            current_station, time = queue.pop(0)
            for candy in candies:
                if candy[0] == current_station:
                    new_time = time + abs(current_station - candy[1]) + (1 if current_station != candy[1] else 0)
                    if candy[1] not in visited:
                        visited.add(candy[1])
                        queue.append((candy[1], new_time))
            if len(visited) == m:
                return time
        return float('inf')

    times = []
    for i in range(1, n + 1):
        times.append(bfs(i))

    return times

