import sys

def min_delivery_time(n, m, deliveries):
    result = []
    for start_station in range(1, n + 1):
        total_time = 0
        visited = [False] * (n + 1)
        for _ in range(m):
            found = False
            for i in range(m):
                if not visited[i]:
                    if deliveries[i][0] == start_station:
                        total_time += abs(deliveries[i][0] - deliveries[i][1])
                        visited[i] = True
                        found = True
                        break
                    elif deliveries[i][1] == start_station:
                        total_time += abs(deliveries[i][1] - deliveries[i][0])
                        visited[i] = True
                        found = True
                        break
            if not found:
                for i in range(m):
                    if not visited[i]:
                        total_time += abs(deliveries[i][0] - start_station) + abs(start_station - deliveries[i][1])
                        visited[i] = True
                        break
        result.append(total_time)
    return result

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    deliveries = [(int(data[2 + 2 * i]), int(data[3 + 2 * i])) for i in range(m)]

